 $tables=['estate_buildings','estate_units','estate_tenants','estate_leases','estate_bank_accounts','estate_bank_transactions','estate_payments','estate_rent_charges','estate_allocations','estate_documents'];if(!in_array($table,$tables,true)||$id<1)throw new InvalidArgumentException('Immobiliendatensatz ungültig.');$q=$pdo->prepare('SELECT * FROM '.$table.' WHERE id=? FOR UPDATE');$q->execute([$id]);$row=$q->fetch();if(!$row)throw new RuntimeException('Immobiliendatensatz nicht gefunden.');if($version!==null&&(int)($row['row_version']??-1)!==$version)throw new RuntimeException('Daten inzwischen geändert. Neu laden; nichts überschrieben.');return $row;
