 elseif($entity==='tenant')$data=['name'=>opsText($in,'name',190,true),'email'=>opsEmail($in),'phone'=>opsText($in,'phone',80),'address'=>opsText($in,'address',2000),'notes'=>opsText($in,'notes',5000)];
 else{$area=financeCents((string)($in['area']??''),'de');if($area<1||$area>100000000)throw new InvalidArgumentException('Wohn-/Nutzfläche positiv, maximal1000000m².');$data=['building_id'=>estateId($in['building_id']??0),'label'=>opsText($in,'label',190,true),'area_units'=>$area,'notes'=>opsText($in,'notes',5000)];}
 return estateTx($pdo,$admin,function()use($pdo,$admin,$entity,$table,$data,$id,$in){$old=$id?estateLock($pdo,$table,$id,opsVersion($in)):[];if($entity==='unit'){estateLock($pdo,'estate_buildings',$data['building_id']);if($old&&(int)$old['building_id']!==$data['building_id'])throw new RuntimeException('Gebäude einer bestehenden Einheit nicht umhängen.');}
