}
function estateAddTerms(PDO $pdo,int $admin,int $lease,array $in):void {
 $date=estateDate((string)($in['valid_from']??''));$data=['rent_cents'=>estateAmount($in,'rent'),'operating_cents'=>estateAmount($in,'operating'),'heating_cents'=>estateAmount($in,'heating')];estateTx($pdo,$admin,function()use($pdo,$admin,$lease,$in,$date,$data){$l=estateLock($pdo,'estate_leases',$lease,opsVersion($in));if($l['occupancy_kind']!=='tenant'||$date<=$l['starts_on']||($l['ends_on']&&$date>$l['ends_on']))throw new RuntimeException('Neue Konditionen nach Vertragsbeginn und innerhalb des Vertrags.');$pdo->prepare('INSERT INTO estate_terms(lease_id,valid_from,rent_cents,operating_cents,heating_cents,created_by) VALUES(?,?,?,?,?,?)')->execute([$lease,$date,...array_values($data),$admin]);$pdo->prepare('UPDATE estate_leases SET row_version=row_version+1 WHERE id=?')->execute([$lease]);estateEvent($pdo,$admin,'lease',$lease,'terms_added',[],['valid_from'=>$date]+$data);});
}
function estateRentSnapshot(PDO $pdo,string $month,int $building=0):array {
 $month=estateMonth($month);$end=(new DateTimeImmutable($month))->format('Y-m-t');$q=$pdo->prepare("SELECT l.*,u.building_id,u.label,t.name tenant_name FROM estate_leases l JOIN estate_units u ON u.id=l.unit_id LEFT JOIN estate_tenants t ON t.id=l.tenant_id WHERE l.occupancy_kind='tenant' AND l.starts_on<=? AND(l.ends_on IS NULL OR l.ends_on>=?)".($building?' AND u.building_id=?':'').' ORDER BY l.id LIMIT 201');$q->execute([$end,$month,...($building?[$building]:[])]);$leases=$q->fetchAll();if(count($leases)>200)throw new RuntimeException('Maximal200 Mietverträge je Monatsvorschau. Gebäude eingrenzen.');$terms=[];$charges=[];if($leases){$ids=array_column($leases,'id');$marks=implode(',',array_fill(0,count($ids),'?'));$q=$pdo->prepare('SELECT * FROM estate_terms WHERE lease_id IN('.$marks.') ORDER BY lease_id,valid_from,id LIMIT 5001');$q->execute($ids);$terms=$q->fetchAll();if(count($terms)>5000)throw new RuntimeException('Konditionslimit erreicht.');$q=$pdo->prepare('SELECT * FROM estate_rent_charges WHERE month=? AND lease_id IN('.$marks.') ORDER BY id');$q->execute([$month,...$ids]);$charges=$q->fetchAll();}return ['month'=>$month,'building'=>$building,'leases'=>$leases,'terms'=>$terms,'charges'=>$charges];
}
function estateRentPlan(array $state):array {
