function estateRentPreview(PDO $pdo,int $admin,string $month,int $building=0):string {
 return estateTx($pdo,$admin,function()use($pdo,$admin,$month,$building){$state=estateRentSnapshot($pdo,$month,$building);$token=bin2hex(random_bytes(32));$pdo->prepare("INSERT INTO estate_proposals(token,kind,admin_id,fingerprint,payload) VALUES(?,'rent',?,?,?)")->execute([$token,$admin,hash('sha256',json_encode($state,JSON_THROW_ON_ERROR)),json_encode(['month'=>$state['month'],'building'=>$building,'plan'=>estateRentPlan($state)],JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR)]);return $token;});
}
function estateGetProposal(PDO $pdo,int $admin,string $token,string $kind):array {$q=$pdo->prepare('SELECT * FROM estate_proposals WHERE token=? AND admin_id=? AND kind=? FOR UPDATE');$q->execute([$token,$admin,$kind]);$p=$q->fetch();if(!$p)throw new RuntimeException('Vorschau nicht gefunden.');if(!$p['applied_at']&&strtotime($p['created_at'].' UTC')<time()-7200)throw new RuntimeException('Vorschau abgelaufen.');return $p;}
