 return estateTx($pdo,$admin,function()use($pdo,$admin,$token){$p=estateGetProposal($pdo,$admin,$token,'rent');if($p['applied_at'])return 0;$payload=json_decode($p['payload'],true,64,JSON_THROW_ON_ERROR);$state=estateRentSnapshot($pdo,$payload['month'],(int)$payload['building']);if(!hash_equals($p['fingerprint'],hash('sha256',json_encode($state,JSON_THROW_ON_ERROR))))throw new RuntimeException('Mietbestand geändert. Vorschau neu erstellen.');$plan=estateRentPlan($state);if($plan['conflicts'])throw new RuntimeException('Offene Konflikte: keine Forderung übernommen.');$count=0;foreach($plan['rows'] as $row){if($row['existing'])continue;$v=$row['charge'];$pdo->prepare('INSERT INTO estate_rent_charges(lease_id,month,due_on,rent_cents,operating_cents,heating_cents,terms_hash,created_by) VALUES(?,?,?,?,?,?,?,?)')->execute([$row['lease_id'],$state['month'],$v['due_on'],$v['rent_cents'],$v['operating_cents'],$v['heating_cents'],$row['terms_hash'],$admin]);$count++;} $pdo->prepare('UPDATE estate_proposals SET applied_at=UTC_TIMESTAMP() WHERE token=?')->execute([$token]);estateEvent($pdo,$admin,'rent_batch',0,'rent_confirmed',[],['month'=>$state['month'],'count'=>$count]);return $count;});
}
function estateManualCharge(PDO $pdo,int $admin,int $lease,array $in):int {
 $month=estateMonth((string)($in['month']??''));$due=estateDate((string)($in['due_on']??''));$data=['rent_cents'=>estateAmount($in,'rent'),'operating_cents'=>estateAmount($in,'operating'),'heating_cents'=>estateAmount($in,'heating')];return estateTx($pdo,$admin,function()use($pdo,$admin,$lease,$month,$due,$data){$l=estateLock($pdo,'estate_leases',$lease);$end=(new DateTimeImmutable($month))->format('Y-m-t');if($l['occupancy_kind']!=='tenant'||$l['starts_on']>$end||($l['ends_on']&&$l['ends_on']<$month))throw new RuntimeException('Kein Mietzeitraum in diesem Monat.');$q=$pdo->prepare('SELECT * FROM estate_rent_charges WHERE lease_id=? AND month=?');$q->execute([$lease,$month]);if($old=$q->fetch()){foreach($data as $k=>$v)if((int)$old[$k]!==$v)throw new RuntimeException('Bestätigte Monatsforderung nicht ersetzen; begründete Korrektur erfassen.');if($old['due_on']!==$due)throw new RuntimeException('Abweichendes Zahlungsziel nicht überschreiben.');return (int)$old['id'];}$pdo->prepare('INSERT INTO estate_rent_charges(lease_id,month,due_on,rent_cents,operating_cents,heating_cents,terms_hash,created_by) VALUES(?,?,?,?,?,?,?,?)')->execute([$lease,$month,$due,...array_values($data),hash('sha256','manual'.json_encode($data)),$admin]);$id=(int)$pdo->lastInsertId();estateEvent($pdo,$admin,'charge',$id,'manual_charge',[],['month'=>$month]+$data);return $id;});
